INSERT INTO `products` (`id`, `name`, `description`, `price`, `img`, `stock`, `bread_type`) VALUES
(4, 'Efsane Karışık Tost (Büyük Boy)', 'Açıklama: Çıtır çıtır kızarmış ekmeğin arasında tam kıvamında eriyen 2 dilim taze kaşar peyniri ve lezzetine doyulmaz 6 dilim nefis sucuk. Klasikleşmiş doyurucu lezzet arayanlar için.', 100.00, 'img/1781270793_643.webp', 0, '14x14 cm'),
(8, 'Uzayan Bol Kaşarlı Tost (Büyük Boy)', 'Açıklama: Sıcaklığıyla eriyip uzayan tam 3 dilim taze kaşar peyniri. Çıtır ekmeğiyle peynir tutkunları için sade, sıcak ve enfes bir seçim.', 100.00, 'img/1781270838_537.webp', 0, '14x14 cm'),
(9, 'Ekstra Sucuklu Tost (Büyük Boy)', 'Açıklama: Sucuk severler için özel hazırladığımız, içinde tam 8 dilim nefis sucuk bulunan doyurucu lezzet. Ekmeğin her köşesinde dolu dolu sucuk keyfi.', 100.00, 'img/1781270888_785.webp', 0, '14x14 cm'),
(10, 'Nefis Karışık Tost (Orta Boy)', 'Açıklama: Çıtır çıtır kızarmış ekmeğin arasında tam kıvamında eriyen 1 dilim taze kaşar peyniri ve lezzet katan 4 dilim nefis sucuk. Pratik, hızlı ve çok lezzetli bir atıştırmalık arayanlar için ideal.', 70.00, 'img/1781271184_264.webp', 18, '11x11 cm'),
(11, 'Sıcak Kaşarlı Tost  (Orta Boy)', 'Açıklama: İçinde sıcaktan eriyip yumuşacık olan 2 dilim taze kaşar peyniri ile hazırlanan klasik lezzet. Sade severler için çayın yanına eşlik edecek en çıtır ve sıcak seçim.', 70.00, 'img/1781271233_529.webp', 18, '11x11 cm'),
(12, 'Çıtır Sucuklu Tost (Orta Boy)', 'Açıklama: Baharatlı ve özenle kızarmış tam 4 dilim nefis sucuk ile ekmek arasında hazırlanan enfes lezzet. Saf sucuk keyfini arayanlar için her lokması dolu dolu.', 70.00, 'img/1781271263_284.webp', 18, '11x11 cm'),
(13, 'Sandviç Ekmeğine Nefis Karışık Tost', 'Çıtır çıtır taze sandviç ekmeği arasında %100 dana sucuk, bol eriyen kaşar peyniri ve özel sosla hazırlanan doyurucu lezzet.', 100.00, 'img/1792261877_687.jpg', 6, 'Sandviç Ekmeği'),
(14, 'Sandviç Ekmeğine Uzayan Bol Kaşarlı Tost', 'Taptaze sandviç ekmeği arasında sıcacık eriyip uzayan bol kaşar peyniriyle hazırlanan dumanı üstünde klasik lezzet.', 100.00, 'img/1792261961_156.jpg', 6, 'Sandviç Ekmeği'),
(15, 'Sandviç Ekmeğine Çıtır Sucuklu Tost', 'Özel sandviç ekmeğinde, yüksek kaliteli %100 dana sucuğun doyurucu ve çıtır çıtır efsane tadı.', 100.00, 'img/1792262009_126.jpg', 6, 'Sandviç Ekmeği');
